CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS clusters (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, environment VARCHAR(40) NOT NULL, region VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS service_instances (id BIGSERIAL PRIMARY KEY, cluster_id BIGINT NOT NULL REFERENCES clusters(id) ON DELETE CASCADE, name VARCHAR(160) NOT NULL, version VARCHAR(80) NOT NULL, replicas INTEGER NOT NULL, cpu_capacity DOUBLE PRECISION NOT NULL, memory_capacity DOUBLE PRECISION NOT NULL, request_capacity DOUBLE PRECISION NOT NULL, status VARCHAR(20) NOT NULL, UNIQUE(cluster_id,name));
CREATE TABLE IF NOT EXISTS shards (id BIGSERIAL PRIMARY KEY, service_id BIGINT NOT NULL REFERENCES service_instances(id) ON DELETE CASCADE, node_id VARCHAR(120), name VARCHAR(160) NOT NULL, capacity DOUBLE PRECISION NOT NULL, current_load DOUBLE PRECISION NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL, UNIQUE(service_id,name));
CREATE TABLE IF NOT EXISTS telemetry_records (id BIGSERIAL PRIMARY KEY, event_id VARCHAR(255) UNIQUE NOT NULL, timestamp TIMESTAMPTZ NOT NULL, cluster_id BIGINT NOT NULL REFERENCES clusters(id), service_id BIGINT NOT NULL REFERENCES service_instances(id), shard_id BIGINT NOT NULL REFERENCES shards(id), request_rate DOUBLE PRECISION NOT NULL, cpu_usage DOUBLE PRECISION NOT NULL, queue_length DOUBLE PRECISION NOT NULL, p95_latency DOUBLE PRECISION NOT NULL, retry_rate DOUBLE PRECISION NOT NULL);
CREATE INDEX IF NOT EXISTS idx_telemetry_shard_time ON telemetry_records(shard_id,timestamp);
CREATE TABLE IF NOT EXISTS predictions (id BIGSERIAL PRIMARY KEY, cluster_id BIGINT NOT NULL REFERENCES clusters(id), service_id BIGINT NOT NULL REFERENCES service_instances(id), shard_id BIGINT NOT NULL REFERENCES shards(id), timestamp TIMESTAMPTZ NOT NULL, overload_probability DOUBLE PRECISION NOT NULL, failure_probability DOUBLE PRECISION NOT NULL, estimated_ttf_seconds INTEGER NOT NULL, confidence DOUBLE PRECISION NOT NULL, risk_level VARCHAR(20) NOT NULL, model_version VARCHAR(80) NOT NULL, fallback_used BOOLEAN NOT NULL, generated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_prediction_shard_time ON predictions(shard_id,timestamp);
